(function() {
  'use strict';
  // Toggle a folded accent when a card is clicked for tactile feedback
  document.addEventListener('click', function(e) {
    const card = e.target.closest('.card');
    if (!card) return;
    card.classList.toggle('card-folded');
  });
})();

