:root {
  /* Origami Shadow Theme - crisp paper folds and sculpted lighting */
  --bg-primary: #f8f6ef;
  --bg-alt: #ede7d8;
  --text-primary: #1f1a13;
  --text-secondary: #4d4135;
  --accent: #d8783b;
  --accent-2: #8c4d1a;
  --border: rgba(31, 26, 19, 0.15);
}

body {
  background: radial-gradient(circle at 16% 18%, #ffffff 0%, #f8f6ef 38%, #ede7d8 100%);
  color: var(--text-primary);
}

.card {
  background: linear-gradient(145deg, #fff 0%, #f7f2e6 40%, #efe6d6 100%);
  border: 1px solid var(--border);
  box-shadow: 0 18px 32px rgba(0, 0, 0, 0.08), 0 0 1px rgba(0, 0, 0, 0.05);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s;
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(0, 0, 0, 0.08), transparent 40%);
  mix-blend-mode: multiply;
  pointer-events: none;
}

.card::after {
  content: '';
  position: absolute;
  inset: 8%;
  border: 1px solid rgba(31, 26, 19, 0.05);
  border-radius: 12px;
  pointer-events: none;
}

.card:hover {
  transform: translateY(-2px) rotateX(0.5deg);
  box-shadow: 0 24px 36px rgba(0, 0, 0, 0.12);
}

.card.card-folded::before {
  background: linear-gradient(140deg, rgba(216, 120, 59, 0.65), transparent 45%);
}

.card-title {
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--accent-2);
}

.badge {
  background: linear-gradient(120deg, #f4e6d2, #f0d9bd);
  color: var(--accent-2);
  border: 1px solid rgba(140, 77, 26, 0.18);
}

.button {
  background: linear-gradient(135deg, #fdf7ec, #f3e5d0);
  color: var(--accent-2);
  border: 1px solid rgba(140, 77, 26, 0.2);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.button:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 26px rgba(0, 0, 0, 0.12);
}
